:13:\"allow-dismiss\";b:0;}i:7;a:8:{s:4:\"slug\";s:41:\"products-list-empty-body-discount-on-cart\";s:7:\"context\";s:24:\"products-list-empty-body\";s:7:\"product\";s:16:\"discount-on-cart\";s:4:\"icon\";s:68:\"https://woocommerce.com/wp-content/uploads/2025/01/cart-discount.jpg\";s:5:\"title\";s:16:\"Discount On Cart\";s:4:\"copy\";s:134:\"WooCommerce discount plugin for automatic cart & product-based discounts. Rule-based tiered pricing, bulk discounts & dynamic pricing.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:50:\"https://woocommerce.com/products/discount-on-cart/\";}i:8;a:8:{s:4:\"slug\";s:48:\"products-list-empty-body-product-recommendations\";s:7:\"context\";s:24:\"products-list-empty-body\";s:7:\"product\";s:35:\"woocommerce-product-recommendations\";s:4:\"icon\";s:105:\"https://woocommerce.com/wp-content/uploads/2019/07/Product_Recommendations_icon-marketplace-160x160-1.png\";s:5:\"title\";s:23:\"Product Recommendations\";s:4:\"copy\";s:131:\"Offer smarter upsells, cross-sells, and \"frequently bought together\" recommendations. Measure their impact with in-depth analytics.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:57:\"https://woocommerce.com/products/product-recommendations/\";}i:9;a:8:{s:4:\"slug\";s:57:\"products-list-empty-body-membership-suite-for-woocommerce\";s:7:\"context\";s:24:\"products-list-empty-body\";s:7:\"product\";s:32:\"membership-suite-for-woocommerce\";s:4:\"icon\";s:84:\"https://woocommerce.com/wp-content/uploads/2023/03/membership-suite-icon-new-160.png\";s:5:\"title\";s:16:\"Membership Suite\";s:4:\"copy\";s:99:\"Add a customizable membership benefits program to your store with Membership Suite for WooCommerce.\";s:11:\"button-text\";s:10:\"Learn More\";s:3:\"url\";s:66:\"https://woocommerce.com/products/membership-suite-for-woocommerce/\";}i:10;a:8:{s:4:\"slug\";s:76:\"products-list-empty-body-buy-once-or-subscribe-for-woocommerce-subscriptions\";s:7:\"context\";s:24:\"products-list-empty-body\";s:7:\