INSERT INTO `wp_posts` VALUES (34,1,'2026-09-10 10:16:57','2026-09-10 10:16:57','<!-- wp:heading {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-text\"}}}},\"textColor\":\"custom-text\"} -->\n<h2 class=\"wp-block-heading has-custom-text-color has-text-color has-link-color\">About Lumen Nook</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-text\"}}}},\"textColor\":\"custom-text\"} -->\n<p class=\"has-custom-text-color has-text-color has-link-color\">Lumen Nook is a concept store focused on computer gear, setup inspiration and helping people create workspaces that suit their needs. Our goal is to make building and improving a computer setup feel simple and approachable.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-text\"}}}},\"textColor\":\"custom-text\"} -->\n<h2 class=\"wp-block-heading has-custom-text-color has-text-color has-link-color\">Our mission</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-text\"}}}},\"textColor\":\"custom-text\"} -->\n<p class=\"has-custom-text-color has-text-color has-link-color\">“We want to combine functionality, personal style and more thoughtful technology choices in one place.”</p>\n<!-- /wp:paragraph -->','About Us','','inherit','closed','closed','','33-revision-v1','','','2026-09-10 10:16:57','2026-09-10 10:16:57','',33,'http://lumen-nook.local/?p=34',0,'revision','',0);
